package depcheck

import (
	"testing"

	"github.com/7shantanu7/kiln/internal/ninja"
	"github.com/7shantanu7/kiln/internal/sandbox"
)

// Graph: gen.h is generated by a codegen step from in.def. a.o is ordered
// after gen.h; b.o and c.o are not.
func testGraph() (*ninja.Graph, map[string]string) {
	edges := []*ninja.Edge{
		{Rule: "CUSTOM_COMMAND", Outputs: []string{"/b/gen.h"}, Explicit: []string{"/s/in.def"}},
		{Rule: "CXX_COMPILER", Outputs: []string{"/b/a.o"}, Explicit: []string{"/s/a.cpp"}, OrderOnly: []string{"/b/gen.h"}, Deps: []string{"/s/a.cpp", "/b/gen.h"}},
		{Rule: "CXX_COMPILER", Outputs: []string{"/b/b.o"}, Explicit: []string{"/s/b.cpp"}, Deps: []string{"/s/b.cpp", "/b/gen.h"}},
		{Rule: "CXX_COMPILER", Outputs: []string{"/b/c.o"}, Explicit: []string{"/s/c.cpp"}},
	}
	g := &ninja.Graph{Dir: "/b", Edges: edges, Producer: map[string]*ninja.Edge{}}
	for _, e := range edges {
		g.Producer[e.Outputs[0]] = e
	}
	cmds := map[string]string{"gen": "/b/gen.h", "cc a": "/b/a.o", "cc b": "/b/b.o", "cc c": "/b/c.o"}
	return g, cmds
}

func step(pid int, cmd string, acc ...sandbox.Access) *sandbox.Process {
	return &sandbox.Process{Pid: pid, Parent: 1, Argv: []string{"/bin/sh", "-c", cmd}, Accesses: acc}
}

func read(p string) sandbox.Access    { return sandbox.Access{Path: p} }
func write(p string) sandbox.Access   { return sandbox.Access{Path: p, Write: true} }
func missing(p string) sandbox.Access { return sandbox.Access{Path: p, Missing: true} }

func TestCheck(t *testing.T) {
	g, cmds := testGraph()
	res := &sandbox.Result{Root: 1, Processes: map[int]*sandbox.Process{
		1: {Pid: 1},
		// codegen reads an undeclared shared file
		2: step(2, "gen", read("/s/in.def"), read("/s/shared.def"), write("/b/gen.h")),
		// a.o is ordered after gen.h: fine
		3: step(3, "cc a", read("/s/a.cpp"), read("/b/gen.h"), write("/b/a.o")),
		// b.o reads gen.h with no ordering: race
		4: step(4, "cc b", read("/s/b.cpp"), read("/b/gen.h"), write("/b/b.o")),
		// c.o failed: gen.h did not exist yet, nothing was written
		5: step(5, "cc c", read("/s/c.cpp"), missing("/b/gen.h")),
		// system files and failed probes of non-generated paths are ignored
		6: step(6, "cc a", read("/usr/include/stdio.h"), missing("/s/nope.h")),
	}}
	rep := Check(g, res, "/s", cmds)
	want := []Finding{
		{Kind: KindRace, Step: "b.o", File: "gen.h", Producer: "gen.h"},
		{Kind: KindRace, Step: "c.o", File: "gen.h", Producer: "gen.h", Missing: true},
		{Kind: KindStale, Step: "gen.h", File: "$SRC/shared.def"},
	}
	if len(rep.Findings) != len(want) {
		t.Fatalf("findings = %+v", rep.Findings)
	}
	for i := range want {
		if rep.Findings[i] != want[i] {
			t.Errorf("finding %d = %+v, want %+v", i, rep.Findings[i], want[i])
		}
	}
	if rep.Steps != 5 {
		t.Errorf("matched %d steps, want 5 (including the failed one)", rep.Steps)
	}
}
